
let settingsTab='general',settingsQuery='',prefs={theme:'jade',language:'zh',launch:true,tray:true,font:'系统默认',codeFont:'SF Mono',autoUpdate:true,beta:false},updateState='idle',wizardStep=0,wizardPlan={name:'xiaosong-mac',agent:true,gateway:true,mode:'lan'},wizardEntry='manual';
try{const saved=JSON.parse(sessionStorage.getItem('xmesh-settings-preview-v1')||'null');if(saved)prefs={...prefs,...saved}}catch{}
function savePrefs(){try{sessionStorage.setItem('xmesh-settings-preview-v1',JSON.stringify(prefs))}catch{}}
const settingsTabs=[['general','通用','sliders'],['diagnostics','存储与诊断','folder'],['about','关于与更新','info']];
const toggle=(id,checked,label)=>`<button type="button" class="setting-switch" role="switch" aria-checked="${checked}" aria-label="${label}" data-pref-toggle="${id}"><i></i></button>`;
const row=(title,desc,control)=>`<div class="setting-row"><div><strong>${title}</strong><p>${desc}</p></div><div class="setting-control">${control}</div></div>`;
const section=(title,content,extra='')=>`<section class="settings-card" ${extra}><h3>${title}</h3>${content}</section>`;
const picker=(id,options,selected)=>`<select id="pref-${id}" data-pref-select="${id}" aria-label="${id==='language'?'界面语言':id==='font'?'界面字体':'代码字体'}">${options.map(([value,name])=>`<option value="${value}" ${value===selected?'selected':''}>${name}</option>`).join('')}</select>`;
function maintenance(){return `<details class="maintenance-tools"><summary>维护工具 ${icon('chevron')}</summary><div><p>需要重新调整初始设备或接入方式时，可以重新运行设置向导。</p><button class="muted-action" data-action="wizard-manual">重新运行设置向导 ${icon('arrow')}</button></div></details>`}
function generalPage(){return section('外观与语言',row('外观','选择适合当前环境的界面配色。',`<div class="theme-choices">${[['system','跟随系统'],['jade','深色'],['light','浅色']].map(([id,name])=>`<button data-theme-choice="${id}" aria-pressed="${prefs.theme===id}"><span class="theme-demo ${id}"></span><span>${name}</span></button>`).join('')}</div>`)+row('界面语言','应用到侧栏、页面和通知。',picker('language',[['zh','简体中文'],['en','English']],prefs.language))+row('界面字体','使用本机已安装的字体。',picker('font',[['系统默认','系统默认'],['PingFang SC','苹方'],['Segoe UI','Segoe UI']],prefs.font))+row('代码字体','终端、标识与配置摘要使用等宽字体。',picker('codeFont',[['SF Mono','SF Mono'],['Menlo','Menlo'],['Consolas','Consolas']],prefs.codeFont)))+section('启动与窗口',row('登录后启动 xmesh','登录系统后自动启动应用。',toggle('launch',prefs.launch,'登录后启动 xmesh'))+row('关闭窗口后保留在菜单栏','后台服务继续运行，可从菜单栏重新打开。',toggle('tray',prefs.tray,'关闭窗口后保留在菜单栏')))+`<div class="settings-context"><span>${icon('info')}</span><p>Agent、Gateway 与 Ingress 的配置可从顶部角色菜单打开。CI 和 Tailnet 的配置在各自模块中管理。</p></div>`+maintenance()}
function diagnosticsPage(){return section('本机数据',row('设备名称','用于在设备列表和网络中识别这台机器。',`<span class="value-text">xiaosong-mac</span>`)+row('数据目录','运行状态、缓存与本机凭据的存放位置。',`<button class="button small" data-action="data-directory">查看位置 ${icon('folder')}</button>`)+row('应用日志','排查本机内核和应用的运行问题。',`<button class="button small" data-action="logs">查看日志位置</button>`))+section('诊断与恢复',row('诊断摘要','查看应用版本、角色状态和连接概况。',`<button class="button small" data-action="diagnostics">查看摘要</button>`)+row('模块配置状态','按模块定位需要处理的配置。',`<button class="button small" data-action="config-health">检查状态</button>`))+maintenance()}
function aboutPage(){return `<section class="about-hero"><div class="about-brand">xmesh<span>.</span></div><h3>连接设备，协同工作。</h3><p>桌面应用 · v0.1.0-beta.6</p><span class="tag">设计预览 · 示例版本</span></section>`+section('应用更新',row('当前版本','v0.1.0-beta.6 · macOS ARM64',`<button class="button small primary" data-action="check-update" ${updateState==='checking'?'disabled':''}>${icon('refresh')}${updateState==='checking'?'正在检查…':'检查更新'}</button>`)+`<div class="update-feedback" role="status">${updateState==='checked'?'示例检查完成 · 当前没有可用更新':updateState==='checking'?'正在检查示例更新状态':'检查后显示可用版本与更新说明。'}</div>`+row('自动检查更新','启动后定期检查可用版本。',toggle('autoUpdate',prefs.autoUpdate,'自动检查更新'))+row('接收预发布版本','提前体验新的功能与改进。',toggle('beta',prefs.beta,'接收预发布版本')))+section('产品信息',row('应用与内核','在诊断信息中查看当前运行版本。',`<button class="plain-link" data-action="diagnostics">版本详情 ${icon('arrow')}</button>`)+row('开源许可','查看组件来源与许可信息。',`<button class="plain-link" data-action="licenses">查看 ${icon('chevron')}</button>`))}
function render(){const page=settingsTab==='general'?generalPage():settingsTab==='diagnostics'?diagnosticsPage():aboutPage();renderModule(`<div class="breadcrumb">应用 <span>/</span><strong>设置</strong></div><div class="page-heading"><div><h1>设置</h1><p>让 xmesh 更贴合你的工作习惯。</p></div><span class="settings-local">${icon('device')}仅作用于这台设备</span></div><div class="settings-layout"><nav class="settings-local-nav" aria-label="设置分类">${settingsTabs.map(([id,name,glyph])=>`<button data-settings-tab="${id}" ${settingsTab===id?'aria-current="page"':''}>${icon(glyph)}<span>${name}</span>${icon('chevron')}</button>`).join('')}</nav><div class="settings-main" id="settings-content">${page}<div class="settings-footnote">应用偏好实时保存 · 角色与模块配置预览确认后生效</div></div></div>`)}
function wizardRender(){const steps=['选择用途','设备与网络','确认设置'];let content;if(wizardStep===0)content=`<p class="drawer-description">选择这台设备需要承担的工作，之后可从顶部角色菜单调整。</p><label class="wizard-option"><input type="checkbox" id="wizard-agent" ${wizardPlan.agent?'checked':''}><span><strong>提供本机工具 · Agent</strong><small>执行命令、文件与桌面操作</small></span></label><label class="wizard-option"><input type="checkbox" id="wizard-gateway" ${wizardPlan.gateway?'checked':''}><span><strong>连接工具客户端 · Gateway</strong><small>接入客户端并路由到设备</small></span></label><p class="small-hint">公网接入可在 Ingress 设置中配置。</p>`;else if(wizardStep===1)content=field('设备名称','wizard-name',wizardPlan.name)+selectField('网络模式','wizard-mode',[['lan','局域网'],['tailnet','Tailnet'],['coexist','局域网与 Tailnet'],['offline','暂不联网']],wizardPlan.mode)+`<p class="small-hint">Tailnet 模式可在网络模块中继续完成凭据连接。</p>`;else content=`${facts([['设备名称',esc(wizardPlan.name)],['角色',[wizardPlan.agent?'Agent':'',wizardPlan.gateway?'Gateway':''].filter(Boolean).join(' · ')],['网络模式',{lan:'局域网',tailnet:'Tailnet',coexist:'局域网与 Tailnet',offline:'暂不联网'}[wizardPlan.mode]]])}<div class="drawer-tip" style="margin-top:20px">完成后进入日常工作界面，后续从设置中的维护工具重新打开向导。</div>`;
 openPanel(wizardEntry==='first'?'欢迎使用 xmesh':'设置向导',`<ol class="wizard-steps">${steps.map((name,i)=>`<li class="${i===wizardStep?'active':i<wizardStep?'done':''}"><span>${i+1}</span>${name}</li>`).join('')}</ol>${content}<p id="wizard-error" class="form-error"></p><div class="form-actions">${wizardStep?'<button class="button" data-action="wizard-back">上一步</button>':'<button class="button quiet" data-action="wizard-skip">稍后设置</button>'}<button class="button primary" data-action="wizard-next">${wizardStep===2?'完成设置':'继续'}</button></div>`,'初始设置')}
function startWizard(entry){wizardEntry=entry;wizardStep=0;if(entry==='first'){try{sessionStorage.setItem('xmesh-first-run-seen-preview','true')}catch{}}wizardRender()}
function finishWizard(){try{sessionStorage.setItem('xmesh-initialized-preview','true')}catch{}closePanel();notify('演示：初始化已完成')}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;const d=t.dataset;if(d.settingsTab){settingsTab=d.settingsTab;render()}
 if(d.prefToggle){prefs[d.prefToggle]=!prefs[d.prefToggle];savePrefs();render();notify('演示偏好已保存')}
 if(d.themeChoice){prefs.theme=d.themeChoice;savePrefs();document.documentElement.dataset.theme=d.themeChoice==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'jade':'light'):d.themeChoice;render()}
 const action=d.action;if(action==='first-run-demo')startWizard('first');if(action==='wizard-manual')startWizard('manual');if(action==='wizard-skip'){try{sessionStorage.setItem('xmesh-initialized-preview','true')}catch{}closePanel();notify('可稍后在维护工具中继续设置')}
 if(action==='wizard-next'){if(wizardStep===0){wizardPlan.agent=$('wizard-agent').checked;wizardPlan.gateway=$('wizard-gateway').checked;if(!wizardPlan.agent&&!wizardPlan.gateway){$('wizard-error').textContent='请选择至少一个角色。';return}}if(wizardStep===1){wizardPlan.name=$('wizard-name').value.trim();wizardPlan.mode=$('wizard-mode').value;if(!/^[a-z0-9][a-z0-9-]{0,62}$/.test(wizardPlan.name)){$('wizard-error').textContent='设备名称使用小写字母、数字和连字符。';return}}if(wizardStep===2){finishWizard();return}wizardStep++;wizardRender()}
 if(action==='wizard-back'){wizardStep--;wizardRender()}
 if(action==='check-update'){updateState='checking';render();setTimeout(()=>{updateState='checked';render()},600)}
 if(action==='data-directory'||action==='logs')openPanel(action==='logs'?'日志位置':'数据位置',`<p class="drawer-description">此处展示本机运行目录的设计位置。</p><div class="resource-location">${action==='logs'?'~/Library/Logs/xmesh':'~/Library/Application Support/xmesh'}</div><p class="small-hint" style="margin-top:16px">正式应用使用内核返回的实际目录。</p><button class="button full" style="margin-top:20px" data-base-action="close">返回设置</button>`,'存储与诊断');
 if(action==='diagnostics'){const states=window.xmeshRolePreview?.get();openPanel('诊断摘要',`${facts([['设备','xiaosong-mac'],['应用版本','v0.1.0-beta.6 · 示例'],['平台','macOS ARM64'],...Object.entries(states||{}).map(([name,r])=>[name,r.enabled?'已开启':'已关闭'])])}<p class="small-hint" style="margin-top:18px">正式应用可导出经脱敏的诊断摘要。</p>`,'本机诊断')}
 if(action==='config-health')openPanel('模块配置状态',`<div class="health-list">${[['Agent','执行目录与限制'],['Gateway','客户端接入与路由'],['Ingress','公网地址与身份'],['CI','仓库与运行器'],['Tailnet','网络策略与中继']].map(([name,copy])=>`<div class="health-item"><span>${name}<small>${copy}</small></span>${state(name==='Ingress'?'待配置':'已配置',name==='Ingress'?'neutral':'ok')}</div>`).join('')}</div>`,'配置诊断');
 if(action==='licenses')openPanel('开源许可',`<p class="drawer-description">此处展示应用及其依赖组件的许可信息。</p><div class="health-list"><div class="health-item"><span>Electron<small>应用运行时</small></span><span class="tag">MIT</span></div><div class="health-item"><span>Preact<small>界面组件</small></span><span class="tag">MIT</span></div></div><p class="small-hint">正式发布时从安装包的许可清单加载完整内容。</p>`,'关于 xmesh');
});
document.addEventListener('change',e=>{if(e.target.dataset.prefSelect){prefs[e.target.dataset.prefSelect]=e.target.value;savePrefs();notify('演示偏好已保存')}});
function settingsHash(){if(location.hash==='#about')settingsTab='about';if(location.hash==='#diagnostics')settingsTab='diagnostics';render()}
window.addEventListener('hashchange',settingsHash);settingsHash();
try{if(new URLSearchParams(location.search).has('first-run')&&sessionStorage.getItem('xmesh-first-run-seen-preview')!=='true')startWizard('first')}catch{}
